import "errors"

var (
	errNegativeRoll        = errors.New("Negative roll is invalid")
	errPinCountExceeds     = errors.New("Pin count exceeds pins on the lane")
	errCannotRollAfterOver = errors.New("Cannot roll after game is over")
	errGameIncomplete      = errors.New("Score cannot be taken until the end of the game")
)

type Game struct {
	rolls       []int
	frame       int // 0-based index of the current frame
	rollInFrame int // 0 or 1
	pinsDown    int // pins knocked down by the first roll of the current frame
}

func NewGame() *Game {
	return &Game{}
